// Every source event owns one packet and exactly one later detection.
// Virtual playback time freezes on pause; no detector samples are generated by drawing.
export const PHOTON_FLIGHT_MS=1400;
export function createPhotonEvents(){return{emitted:0,detected:0,discarded:0,nextId:1,packets:[]}}
export function launchPhoton(events,start,hit){const packet={id:events.nextId++,start,arrival:start+PHOTON_FLIGHT_MS,hit};events.emitted++;events.packets.push(packet);return packet}
export function arrivePhotons(events,now){const arrived=events.packets.filter(p=>p.arrival<=now);events.packets=events.packets.filter(p=>p.arrival>now);events.detected+=arrived.length;return arrived}
export function discardPhotons(events){events.discarded+=events.packets.length;events.packets=[]}
